return ['domain'=>'fast-index','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'nl_NL','project-id-version'=>'Fast Index 3.0.0','pot-creation-date'=>'2026-10-14T23:43:40+00:00','po-revision-date'=>'2026-10-14 23:54+0000','x-generator'=>'Fast Index translation build','messages'=>['Fast Index for Google Indexing API'=>'Fast Index for Google Indexing API','Sends new, updated and deleted posts to the Google Indexing API so Google can crawl them sooner.'=>'Verzendt nieuwe, bijgewerkte en verwijderde berichten naar de Google Indexing API, zodat Google ze eerder kan crawlen.','Samet AKIN'=>'Samet AKIN','https://www.linkedin.com/in/samet-akin/'=>'https://www.linkedin.com/in/samet-akin/','The file is empty or too large to be a service account key.'=>'Het bestand is leeg of te groot om een serviceaccountsleutel te zijn.','The file is not valid JSON.'=>'Het bestand is geen geldige JSON.','The file is not a Google service account key.'=>'Het bestand is geen Google-serviceaccountsleutel.','The key does not contain a valid client email.'=>'De sleutel bevat geen geldig client-e-mailadres.','The key does not contain a valid private key.'=>'De sleutel bevat geen geldige privésleutel.','Settings saved.'=>'Instellingen opgeslagen.','Choose a .json key file.'=>'Kies een .json-sleutelbestand.','The service account key was deleted.'=>'De serviceaccountsleutel is verwijderd.','The service account key was not found.'=>'De serviceaccountsleutel is niet gevonden.','%1$s: %2$s'=>'%1$s: %2$s','See the premium plan'=>'Bekijk het premiumplan','The key of %s was saved.'=>'De sleutel van %s is opgeslagen.','Sorry, you are not allowed to do that.'=>'Je hebt geen toestemming om dat te doen.','Fast Index'=>'Fast Index','History'=>'Geschiedenis','Help & FAQ'=>'Hulp en FAQ','Not sent: no service account key'=>'Niet verzonden: geen serviceaccountsleutel','Not sent: every key was paused'=>'Niet verzonden: alle sleutels waren gepauzeerd','Not sent: OpenSSL is missing'=>'Niet verzonden: OpenSSL ontbreekt','No answer from Google'=>'Geen antwoord van Google','Fast Index tries again when a key is ready.'=>'Fast Index probeert het opnieuw zodra er een sleutel klaar is.','Sorry, you are not allowed to access this page.'=>'Je hebt geen toestemming om deze pagina te bekijken.','Upgrade'=>'Upgraden','Title of the Freemius page with the plansPricing'=>'Prijzen','Button of the Freemius opt-in screenSkip'=>'Overslaan','Button of the Freemius opt-in screenAllow & Continue'=>'Toestaan en doorgaan','Unknown notification type.'=>'Onbekend meldingstype.','Google sent an unexpected response.'=>'Google heeft een onverwacht antwoord gestuurd.','The private key of the service account could not be read.'=>'De privésleutel van het serviceaccount kon niet worden gelezen.','The request to Google could not be signed.'=>'Het verzoek aan Google kon niet worden ondertekend.','The PHP OpenSSL extension is not available, so requests to Google cannot be signed. Ask your hosting provider to enable OpenSSL for PHP.'=>'De PHP-extensie OpenSSL is niet beschikbaar, dus verzoeken aan Google kunnen niet worden ondertekend. Vraag je hostingprovider om OpenSSL voor PHP in te schakelen.','Could not connect to Google.'=>'Kan geen verbinding maken met Google.','Google answered with HTTP status %d.'=>'Google antwoordde met HTTP-status %d.','Getting started'=>'Aan de slag','Settings explained'=>'Instellingen uitgelegd','Troubleshooting'=>'Probleemoplossing','FAQ'=>'FAQ','Still need help?'=>'Heb je nog hulp nodig?','Read this first. Google says: %1$s For other pages, Google may accept a notification, but nothing in its documentation promises that the page will be crawled or indexed sooner. See the FAQ and Google\'s documentation: %2$s.'=>'Lees dit eerst. Google zegt: %1$s Voor andere pagina\'s kan Google een melding accepteren, maar nergens in de documentatie staat een belofte dat de pagina sneller wordt gecrawld of geïndexeerd. Zie de FAQ en de documentatie van Google: %2$s.','"The Indexing API can only be used to crawl pages with either JobPosting or BroadcastEvent embedded in a VideoObject."'=>'“De Indexing API kan alleen worden gebruikt om pagina\'s te crawlen met JobPosting of met BroadcastEvent ingesloten in een VideoObject.”','Indexing API quickstart'=>'Snelstart voor de Indexing API','Fast Index tells the Google Indexing API when a post is published, changed or removed. For this, Google needs a service account that you create once in Google Cloud. The steps below follow Google\'s own instructions.'=>'Fast Index meldt de Google Indexing API wanneer een bericht wordt gepubliceerd, gewijzigd of verwijderd. Hiervoor heeft Google een serviceaccount nodig dat je eenmalig in Google Cloud aanmaakt. De stappen hieronder volgen de eigen instructies van Google.','Create a Google Cloud project and turn on the API'=>'Maak een Google Cloud-project en schakel de API in','Open the %1$s and select or create a project. Then enable the %2$s for that project (Google\'s documentation calls it the Indexing API). Google also offers a setup tool that creates a project and enables the API in one step; it is linked from %3$s.'=>'Open de %1$s en selecteer of maak een project. Schakel daarna de %2$s in voor dat project (in de documentatie van Google heet die de Indexing API). Google biedt ook een installatiehulpmiddel dat in één stap een project maakt en de API inschakelt; je vindt het op %3$s.','Google Cloud console'=>'Google Cloud-console','Web Search Indexing API'=>'Web Search Indexing API','Google\'s prerequisites page'=>'de pagina met vereisten van Google','Create a service account'=>'Maak een serviceaccount','In the Google Cloud console open the %1$s page, choose your project and click %2$s. Enter a name. You can skip the optional steps about access (IAM roles). Click %3$s.'=>'Open in de Google Cloud-console de pagina %1$s, kies je project en klik op %2$s. Voer een naam in. De optionele stappen over toegang (IAM-rollen) kun je overslaan. Klik op %3$s.','Service accounts'=>'Serviceaccounts (Service accounts)','Create service account'=>'Serviceaccount maken (Create service account)','Done'=>'Gereed (Done)','Download a JSON key'=>'Download een JSON-sleutel','Click the email address of the new service account and open the %1$s tab. Click %2$s, choose %3$s, select %4$s as the key type and click %5$s. The file downloads once and Google cannot give it to you again. Keep it private and never share or post it. If Google says you cannot create keys, your organization may block key creation with a policy; ask your Google Cloud administrator.'=>'Klik op het e-mailadres van het nieuwe serviceaccount en open het tabblad %1$s. Klik op %2$s, kies %3$s, selecteer %4$s als sleuteltype en klik op %5$s. Het bestand wordt één keer gedownload en Google kan het je niet opnieuw geven. Houd het privé en deel of plaats het nooit ergens. Als Google zegt dat je geen sleutels kunt maken, blokkeert je organisatie het maken van sleutels mogelijk met een beleid; vraag het aan je Google Cloud-beheerder.','Keys'=>'Sleutels (Keys)','Add key'=>'Sleutel toevoegen (Add key)','Create new key'=>'Nieuwe sleutel maken (Create new key)','JSON'=>'JSON','Create'=>'Maken (Create)','Add the service account as an Owner in Search Console'=>'Voeg het serviceaccount toe als Eigenaar in Search Console','Open Search Console and choose the verified property of your site: a Domain property, or a URL-prefix property that matches your site address exactly, including https and www. Go to %1$s, then %2$s, click %3$s, enter the email address of the service account (the %6$s value in the JSON file; it ends in .iam.gserviceaccount.com) and choose %4$s as the permission. Google describes this in %5$s.'=>'Open Search Console en kies de geverifieerde property van je site: een domeinproperty of een URL-voorvoegselproperty die exact overeenkomt met je siteadres, inclusief https en www. Ga naar %1$s en dan naar %2$s, klik op %3$s, voer het e-mailadres van het serviceaccount in (de waarde %6$s in het JSON-bestand; het eindigt op .iam.gserviceaccount.com) en kies %4$s als rechten. Google beschrijft dit in %5$s.','Menu entry in Google Search ConsoleSettings'=>'Instellingen','Users and permissions'=>'Gebruikers en rechten','Add user'=>'Gebruiker toevoegen','Owner'=>'Eigenaar','Search Console Help'=>'Search Console-help','Upload the key to Fast Index'=>'Upload de sleutel naar Fast Index','Open the Fast Index settings. Under %1$s choose the .json file (%2$s) and click %3$s. The screen then lists the email address and key ID of the key. The private key is stored in your database and is never shown.'=>'Open de instellingen van Fast Index. Kies onder %1$s het .json-bestand (%2$s) en klik op %3$s. Het scherm toont daarna het e-mailadres en de sleutel-ID van de sleutel. De privésleutel wordt in je database opgeslagen en wordt nooit getoond.','Upload Google Service Account Key'=>'Google-serviceaccountsleutel uploaden','JSON Key File'=>'JSON-sleutelbestand','Upload key'=>'Sleutel uploaden','Choose what to send'=>'Kies wat er wordt verzonden','In the settings keep %1$s on %2$s, check the %3$s to send and click %4$s. Every option is explained under Settings explained.'=>'Laat in de instellingen %1$s op %2$s staan, vink de %3$s aan die je wilt verzenden en klik op %4$s. Elke optie wordt uitgelegd onder Instellingen uitgelegd.','Status'=>'Status','Active'=>'Actief','Post Types'=>'Berichttypen','Save'=>'Opslaan','Publish a test post and check History'=>'Publiceer een testbericht en bekijk Geschiedenis','Publish a post. A short while later (when WordPress runs its scheduled tasks) it appears under Fast Index, %1$s. %2$s means Google accepted the notification; it does not mean the page is indexed. Any other code is explained under Troubleshooting.'=>'Publiceer een bericht. Even later (zodra WordPress zijn geplande taken uitvoert) verschijnt het onder Fast Index, %1$s. %2$s betekent dat Google de melding heeft geaccepteerd; het betekent niet dat de pagina is geïndexeerd. Elke andere code wordt uitgelegd onder Probleemoplossing.','Prefer a video? %s The video was recorded for an earlier version, so some screens may look different from this guide.'=>'Liever een video? %s De video is opgenomen voor een eerdere versie, dus sommige schermen kunnen er anders uitzien dan in deze handleiding.','Watch the setup video on YouTube (external link, opens in a new tab)'=>'Bekijk de installatievideo op YouTube (externe link, opent in een nieuw tabblad)','Active: Fast Index sends the notifications chosen on the settings screen. Passive: nothing is sent. A post saved while Passive is not queued for later.'=>'Actief: Fast Index verzendt de meldingen die op het instellingenscherm zijn gekozen. Passief: er wordt niets verzonden. Een bericht dat wordt opgeslagen terwijl de status Passief is, komt niet in de wachtrij voor later.','Switch to Passive before a bulk import or a large edit, so that hundreds of addresses do not use up Google\'s daily quota. Your keys and history are kept.'=>'Schakel over naar Passief vóór een bulkimport of een grote bewerking, zodat honderden adressen niet het dagelijkse quotum van Google opmaken. Je sleutels en geschiedenis blijven bewaard.','Only the checked post types are sent, and at least one is required. The free version offers Posts; media attachments are never offered.'=>'Alleen de aangevinkte berichttypen worden verzonden, en minstens één is vereist. De gratis versie biedt Berichten aan; media-bijlagen worden nooit aangeboden.','Posts'=>'Berichten','Check another type when its pages should be sent too, for example a custom post type that holds job postings or live videos.'=>'Vink een ander type aan als de pagina\'s ervan ook moeten worden verzonden, bijvoorbeeld een aangepast berichttype met vacatures of livevideo\'s.','Daily Limit for Old Posts'=>'Dagelijkse limiet voor oude berichten','Sends published posts that Google has never accepted from this site, newest first, in small batches every hour. The limit counts every successful notification of the last 24 hours, new posts included, and can be set from 0 to 10,000. The size of each batch is random, from 0 up to a third of the daily limit, so some hours send nothing.'=>'Verzendt gepubliceerde berichten die Google van deze site nog nooit heeft geaccepteerd, nieuwste eerst, in kleine batches elk uur. De limiet telt elke geslaagde melding van de afgelopen 24 uur, nieuwe berichten inbegrepen, en kan worden ingesteld op 0 tot 10.000. De omvang van elke batch is willekeurig, van 0 tot een derde van de dagelijkse limiet, dus sommige uren wordt er niets verzonden.','0 (off)'=>'0 (uit)','Turn it on after your new posts are sent correctly. Keep the limit low enough to leave room for new posts within Google\'s daily quota (see the FAQ).'=>'Zet dit aan nadat je nieuwe berichten correct worden verzonden. Houd de limiet laag genoeg om ruimte te laten voor nieuwe berichten binnen het dagelijkse quotum van Google (zie de FAQ).','Post Events'=>'Berichtgebeurtenissen','Publish: a post becomes published. Edit: a post that is already published is saved again. Trash: a published post is moved to the trash or deleted, and Google is told that the address was removed. Changing a published post back to draft or private is not sent.'=>'Publiceren: een bericht wordt gepubliceerd. Bewerken: een bericht dat al is gepubliceerd wordt opnieuw opgeslagen. Prullenbak: een gepubliceerd bericht wordt naar de prullenbak verplaatst of verwijderd, en Google krijgt te horen dat het adres is verwijderd. Een gepubliceerd bericht terugzetten naar concept of privé wordt niet verzonden.','Publish. With the premium plan: Publish and Edit.'=>'Publiceren. Met het premiumplan: Publiceren en Bewerken.','Turn on Edit if changed content should be recrawled. Turn on Trash if removed pages should be reported; Google asks that the address already returns 404 or 410, or has a noindex tag, when you send a removal.'=>'Zet Bewerken aan als gewijzigde inhoud opnieuw moet worden gecrawld. Zet Prullenbak aan als verwijderde pagina\'s moeten worden gemeld; Google vraagt dat het adres al 404 of 410 teruggeeft, of een noindex-tag heeft, wanneer je een verwijdering verzendt.','Exclude Categories'=>'Categorieën uitsluiten','A post in at least one checked category is never sent, whether it is new, changed, removed or part of an old-post batch, even if it is also in other categories.'=>'Een bericht in minstens één aangevinkte categorie wordt nooit verzonden, of het nu nieuw, gewijzigd, verwijderd of onderdeel van een batch oude berichten is, ook als het daarnaast in andere categorieën staat.','No category is excluded'=>'Geen enkele categorie is uitgesloten','Use it for content you do not want Google to hear about, for example internal or duplicate material.'=>'Gebruik dit voor inhoud waarvan je niet wilt dat Google ervan hoort, bijvoorbeeld interne of dubbele inhoud.','Delete data on uninstall'=>'Gegevens verwijderen bij deïnstallatie','Applies when the plugin is deleted from the Plugins screen, not when it is deactivated. Settings, keys and history are removed, on every site of a multisite network. Records kept by Freemius are not touched.'=>'Geldt wanneer de plugin wordt verwijderd via het scherm Plugins, niet wanneer deze wordt gedeactiveerd. Instellingen, sleutels en geschiedenis worden verwijderd, op elke site van een multisitenetwerk. Gegevens die Freemius bewaart, blijven ongemoeid.','Off'=>'Uit','Turn it on only if you are removing Fast Index for good. The key also stays valid in Google Cloud until you delete it there.'=>'Zet dit alleen aan als je Fast Index definitief verwijdert. De sleutel blijft ook geldig in Google Cloud totdat je hem daar verwijdert.','Reads the .json key that you downloaded from Google Cloud, checks it and stores it in the database, not in the uploads folder. Each stored key is listed with its email address, key ID and the last answer from Google. A key can be deleted from the list.'=>'Leest de .json-sleutel die je uit Google Cloud hebt gedownload, controleert deze en slaat hem op in de database, niet in de uploadmap. Elke opgeslagen sleutel staat in de lijst met zijn e-mailadres, sleutel-ID en het laatste antwoord van Google. Een sleutel kan uit de lijst worden verwijderd.','No key'=>'Geen sleutel','Upload again after you create a new key. Uploading a key for an email address that is already stored replaces the stored key.'=>'Upload opnieuw nadat je een nieuwe sleutel hebt gemaakt. Een sleutel uploaden voor een e-mailadres dat al is opgeslagen, vervangt de opgeslagen sleutel.','Publish: a post is published.'=>'Publiceren: een bericht wordt gepubliceerd.','Edit: a published post is saved again.'=>'Bewerken: een gepubliceerd bericht wordt opnieuw opgeslagen.','Trash: a published post is moved to the trash or deleted.'=>'Prullenbak: een gepubliceerd bericht gaat naar de prullenbak of wordt verwijderd.','Active sends notifications to Google. Passive pauses everything; your keys and history are kept.'=>'Actief verzendt meldingen naar Google. Passief pauzeert alles; je sleutels en geschiedenis blijven bewaard.','Only the checked types are sent. Media attachments are not listed.'=>'Alleen de aangevinkte typen worden verzonden. Media-bijlagen staan niet in de lijst.','How many old posts may be sent per day, in small hourly batches. 0 turns this off.'=>'Hoeveel oude berichten er per dag mogen worden verzonden, in kleine batches per uur. Met 0 zet je dit uit.','Publish: a post is published. Edit: a published post is saved again. Trash: a published post is moved to the trash or deleted.'=>'Publiceren: een bericht wordt gepubliceerd. Bewerken: een gepubliceerd bericht wordt opnieuw opgeslagen. Prullenbak: een gepubliceerd bericht gaat naar de prullenbak of wordt verwijderd.','Posts in a checked category are never sent.'=>'Berichten in een aangevinkte categorie worden nooit verzonden.','Off by default: deleting the plugin keeps your settings, keys and history, so a reinstall continues where you left off.'=>'Standaard uit: als je de plugin verwijdert, blijven je instellingen, sleutels en geschiedenis bewaard, zodat een herinstallatie verdergaat waar je gebleven was.','Pages and custom post types are part of the premium plan, a separate package.'=>'Pagina\'s en aangepaste berichttypen horen bij het premiumplan, een apart pakket.','Edit and Trash are part of the premium plan, a separate package.'=>'Bewerken en Prullenbak horen bij het premiumplan, een apart pakket.','This setting is part of the premium plan, a separate package.'=>'Deze instelling hoort bij het premiumplan, een apart pakket.','The free version uses one key, and a new upload replaces it. Several keys are part of the premium plan, a separate package.'=>'De gratis versie gebruikt één sleutel, en een nieuwe upload vervangt die. Meerdere sleutels horen bij het premiumplan, een apart pakket.','403: "Permission denied. Failed to verify the URL ownership"'=>'403: “Permission denied. Failed to verify the URL ownership”','Google answers 403 when the service account is not an Owner of the Search Console property that contains the page address (%s). Common reasons: the account was never added, it was added with a lower permission than Owner, the property is for another address (http or https, www or no www, another site), or the Indexing API is not enabled in the project that owns the key.'=>'Google antwoordt met 403 wanneer het serviceaccount geen Eigenaar is van de Search Console-property die het paginaadres bevat (%s). Veelvoorkomende oorzaken: het account is nooit toegevoegd, het is toegevoegd met lagere rechten dan Eigenaar, de property hoort bij een ander adres (http of https, www of zonder www, een andere site), of de Indexing API is niet ingeschakeld in het project waartoe de sleutel behoort.','Google\'s error list'=>'foutenlijst van Google','In Search Console open the property, go to Settings and Users and permissions, and check that the service account email is listed with the permission Owner. Make sure the property matches your site address exactly (a Domain property covers every address). Then check in Google Cloud that the Web Search Indexing API is enabled for the key\'s project. After a 403 Fast Index pauses the key for six hours; to retry at once, delete the key on the settings screen and upload it again.'=>'Open in Search Console de property, ga naar Instellingen en Gebruikers en rechten, en controleer of het e-mailadres van het serviceaccount in de lijst staat met de rechten Eigenaar. Zorg dat de property exact overeenkomt met je siteadres (een domeinproperty dekt elk adres). Controleer daarna in Google Cloud of de Web Search Indexing API is ingeschakeld voor het project van de sleutel. Na een 403 pauzeert Fast Index de sleutel zes uur; om direct opnieuw te proberen, verwijder je de sleutel op het instellingenscherm en upload je hem opnieuw.','401: Unauthorized, or the key is refused'=>'401: Unauthorized, of de sleutel wordt geweigerd','Google did not accept the key. The key may have been deleted or disabled in Google Cloud, the uploaded file may be an older key, or the clock of your server may be far off, because the signed request carries the current time. Any 4xx answer to the request for an access token is treated the same way.'=>'Google heeft de sleutel niet geaccepteerd. De sleutel is mogelijk verwijderd of uitgeschakeld in Google Cloud, het geüploade bestand is mogelijk een oudere sleutel, of de klok van je server loopt ver mis, omdat het ondertekende verzoek de huidige tijd bevat. Elk 4xx-antwoord op het verzoek om een toegangstoken wordt op dezelfde manier behandeld.','Create a new JSON key (Service accounts, your account, Keys, Add key, Create new key, JSON), upload it on the settings screen (the same email address replaces the stored key) and check that your server time is correct. The key is paused for six hours after a 401; deleting it and uploading it again ends the pause.'=>'Maak een nieuwe JSON-sleutel (Serviceaccounts, je account, Sleutels, Sleutel toevoegen, Nieuwe sleutel maken, JSON), upload deze op het instellingenscherm (hetzelfde e-mailadres vervangt de opgeslagen sleutel) en controleer of de tijd van je server klopt. De sleutel is zes uur gepauzeerd na een 401; verwijderen en opnieuw uploaden beëindigt de pauze.','429: Too Many Requests'=>'429: Too Many Requests','The quota of Google is used up. Google\'s default is 200 publish requests per day for each Google Cloud project (%s). New, changed and removed addresses all count, and all keys of one project share the same quota.'=>'Het quotum van Google is op. De standaardlimiet van Google is 200 publicatieverzoeken per dag per Google Cloud-project (%s). Nieuwe, gewijzigde en verwijderde adressen tellen allemaal mee, en alle sleutels van één project delen hetzelfde quotum.','quota page'=>'quotapagina','Wait: Fast Index pauses the key for six hours. If the premium plan keeps several keys, the others are tried meanwhile. Lower the daily limit for old posts if you use it, and turn Fast Index to Passive during bulk imports. If you need more, ask Google for more quota on the %s; Google notes that quota may increase or decrease based on document quality.'=>'Wacht: Fast Index pauzeert de sleutel zes uur. Als het premiumplan meerdere sleutels bewaart, worden intussen de andere geprobeerd. Verlaag de dagelijkse limiet voor oude berichten als je die gebruikt, en zet Fast Index op Passief tijdens bulkimports. Heb je meer nodig, vraag Google dan op de %s om meer quotum; Google merkt op dat het quotum kan toenemen of afnemen op basis van documentkwaliteit.','"%s", or a 5xx code'=>'“%s”, of een 5xx-code','Your server could not reach Google within 15 seconds (firewall, DNS or a slow connection), Google had a temporary problem, or its answer could not be read. These answers do not pause a key.'=>'Je server kon Google niet binnen 15 seconden bereiken (firewall, DNS of een trage verbinding), Google had een tijdelijk probleem, of het antwoord kon niet worden gelezen. Deze antwoorden pauzeren een sleutel niet.','Allow outgoing HTTPS requests to oauth2.googleapis.com and indexing.googleapis.com, and try again later. Saving or publishing another post sends a new notification.'=>'Sta uitgaande HTTPS-verzoeken naar oauth2.googleapis.com en indexing.googleapis.com toe en probeer het later opnieuw. Als je een ander bericht opslaat of publiceert, wordt een nieuwe melding verzonden.','A red notice says the PHP OpenSSL extension is not available, or the status "%s"'=>'Een rode melding zegt dat de PHP-extensie OpenSSL niet beschikbaar is, of de status “%s”','Fast Index signs its requests to Google with OpenSSL. PHP without OpenSSL cannot do that, so nothing can be sent. Each notification appears in History with this status and is not sent later.'=>'Fast Index ondertekent zijn verzoeken aan Google met OpenSSL. PHP zonder OpenSSL kan dat niet, dus er kan niets worden verzonden. Elke melding verschijnt met deze status in Geschiedenis en wordt later niet verzonden.','Ask your hosting provider to enable the OpenSSL extension for the PHP version your site uses. The system information below shows whether OpenSSL is available. Then save the posts that should reach Google again; if old-post sending is on, the hourly batches also pick up posts that never reached Google.'=>'Vraag je hostingprovider om de OpenSSL-extensie in te schakelen voor de PHP-versie die je site gebruikt. De systeeminformatie hieronder laat zien of OpenSSL beschikbaar is. Sla daarna de berichten die Google moeten bereiken opnieuw op; als het verzenden van oude berichten aan staat, pikken de batches per uur ook berichten op die Google nooit hebben bereikt.','History shows "%1$s" or "%2$s"'=>'Geschiedenis toont “%1$s” of “%2$s”','No key is stored on the settings screen, or every stored key is paused for six hours because Google answered 401, 403 or 429. Without a key the notification is only recorded. While every key is paused, the notification waits, and History shows "%1$s" under it: it is sent when the first key is ready again, or soon after you upload a key. For each address only the newest event waits; at most %2$s notifications wait, for up to three days.'=>'Er is geen sleutel opgeslagen op het instellingenscherm, of elke opgeslagen sleutel is zes uur gepauzeerd omdat Google 401, 403 of 429 antwoordde. Zonder sleutel wordt de melding alleen vastgelegd. Zolang alle sleutels gepauzeerd zijn, wacht de melding en toont Geschiedenis er “%1$s” onder: ze wordt verzonden zodra de eerste sleutel weer klaar is, of kort nadat je een sleutel uploadt. Per adres wacht alleen de nieuwste gebeurtenis; er wachten hoogstens %2$s meldingen, tot drie dagen lang.','Upload a key on the settings screen. For a paused key, read the entry for its code above. A post that Google has not accepted yet counts as Total Waiting on the History screen: save it again to send it. With the premium plan, the hourly batches of old posts can pick it up too.'=>'Upload een sleutel op het instellingenscherm. Lees voor een gepauzeerde sleutel hierboven het item over de code ervan. Een bericht dat Google nog niet heeft geaccepteerd, telt mee als Totaal wachtend op het scherm Geschiedenis: sla het opnieuw op om het te verzenden. Met het premiumplan kunnen ook de batches per uur van oude berichten het oppikken.','Posts are published but nothing appears in History, or it appears much later'=>'Berichten zijn gepubliceerd, maar er verschijnt niets in Geschiedenis, of pas veel later','Fast Index queues each notification as a WordPress scheduled task (WP-Cron), so saving a post never waits for Google. WP-Cron runs when someone visits the site. If wp-config.php sets DISABLE_WP_CRON to true, WordPress does not start it, and the queue only moves when a real cron job calls wp-cron.php. Sites with very few visits can run late too.'=>'Fast Index zet elke melding in de wachtrij als een geplande WordPress-taak (WP-Cron), zodat het opslaan van een bericht nooit op Google wacht. WP-Cron draait wanneer iemand de site bezoekt. Als wp-config.php DISABLE_WP_CRON op true zet, start WordPress het niet en komt de wachtrij alleen in beweging wanneer een echte cronjob wp-cron.php aanroept. Sites met heel weinig bezoekers kunnen ook te laat draaien.','If you disabled WP-Cron on purpose, set up a real cron job on your server that runs every 5 minutes, for example %1$s or, with WP-CLI, %2$s. Otherwise remove DISABLE_WP_CRON from wp-config.php. The system information below shows whether it is set.'=>'Als je WP-Cron bewust hebt uitgeschakeld, stel dan op je server een echte cronjob in die elke 5 minuten draait, bijvoorbeeld %1$s of, met WP-CLI, %2$s. Verwijder anders DISABLE_WP_CRON uit wp-config.php. De systeeminformatie hieronder laat zien of het is ingesteld.','A post is missing from History'=>'Een bericht ontbreekt in Geschiedenis','Fast Index skips a post when Status is Passive, when its post type or the event (Publish, Edit, Trash) is not checked, when it is in an excluded category, or when it is not published. Nothing is written to History then.'=>'Fast Index slaat een bericht over wanneer Status op Passief staat, wanneer het berichttype of de gebeurtenis (Publiceren, Bewerken, Prullenbak) niet is aangevinkt, wanneer het in een uitgesloten categorie staat, of wanneer het niet is gepubliceerd. Er wordt dan niets in Geschiedenis geschreven.','Check the settings above. Changing a setting does not send earlier saves: after you fix the cause, save the post again to send it. If old-post sending is on, posts that never reached Google are also picked up by the hourly batches.'=>'Controleer de instellingen hierboven. Een gewijzigde instelling verzendt eerder opgeslagen versies niet: sla het bericht nadat je de oorzaak hebt verholpen opnieuw op om het te verzenden. Als het verzenden van oude berichten aan staat, worden berichten die Google nooit hebben bereikt ook opgepikt door de batches per uur.','Old posts are not sent, or the message "%s" appears'=>'Oude berichten worden niet verzonden, of de melding “%s” verschijnt','There are no posts to send now. Check your settings and the daily limit.'=>'Er zijn nu geen berichten om te verzenden. Controleer je instellingen en de dagelijkse limiet.','The daily limit is 0, Status is Passive, the daily limit was already reached in the last 24 hours (new posts count too), no key is available, or every eligible post was sent. Each batch has a random size, so a run can also be empty by chance.'=>'De dagelijkse limiet is 0, Status staat op Passief, de dagelijkse limiet is in de afgelopen 24 uur al bereikt (nieuwe berichten tellen ook mee), er is geen sleutel beschikbaar, of alle in aanmerking komende berichten zijn verzonden. Elke batch heeft een willekeurige grootte, dus een uitvoering kan ook bij toeval leeg zijn.','Check the daily limit and the counters on the History screen (Total Waiting shows how many posts have not been accepted by Google yet). Run the batch again later; it also runs every hour on its own.'=>'Controleer de dagelijkse limiet en de tellers op het scherm Geschiedenis (Totaal wachtend toont hoeveel berichten Google nog niet heeft geaccepteerd). Voer de batch later opnieuw uit; hij draait ook elk uur vanzelf.','A notice about keys stored in a public folder, or "%s"'=>'Een melding over sleutels in een openbare map, of “%s”','Fast Index could not finish moving your service account keys to the database.'=>'Fast Index kon het verplaatsen van je serviceaccountsleutels naar de database niet voltooien.','Version 2.x saved key files in the uploads folder, where anyone who knew the address could download them. Version 3 moves each key into the database and deletes the file. The first notice recommends replacing those keys. The second notice means one file could not be read, found or deleted; it names the file.'=>'Versie 2.x sloeg sleutelbestanden op in de uploadmap, waar iedereen die het adres kende ze kon downloaden. Versie 3 verplaatst elke sleutel naar de database en verwijdert het bestand. De eerste melding raadt aan die sleutels te vervangen. De tweede melding betekent dat één bestand niet kon worden gelezen, gevonden of verwijderd; ze noemt het bestand.','Create a new JSON key in Google Cloud, upload it on the settings screen (the same email address replaces the stored key), then delete the old key on the Keys tab of the service account in Google Cloud. If a file could not be deleted, delete it from the uploads folder yourself. Both notices have a link that hides them for good.'=>'Maak in Google Cloud een nieuwe JSON-sleutel, upload deze op het instellingenscherm (hetzelfde e-mailadres vervangt de opgeslagen sleutel) en verwijder daarna in Google Cloud de oude sleutel op het tabblad Sleutels van het serviceaccount. Kon een bestand niet worden verwijderd, verwijder het dan zelf uit de uploadmap. Beide meldingen hebben een link waarmee je ze voorgoed verbergt.','On a multisite network, one site sends and another does not'=>'Op een multisitenetwerk verzendt de ene site wel en de andere niet','Settings, keys, history and the schedule belong to each site. Network activation sets up every site, but a key uploaded on one site is not shared with the others, and Fast Index has no network admin screen.'=>'Instellingen, sleutels, geschiedenis en het schema horen bij elke site afzonderlijk. Netwerkactivering stelt elke site in, maar een sleutel die op één site is geüpload, wordt niet met de andere gedeeld, en Fast Index heeft geen netwerkbeheerscherm.','Open Fast Index on each site and upload a key there. The same key file may be used on several sites. Their notifications then share the quota of the key\'s Google Cloud project.'=>'Open Fast Index op elke site en upload daar een sleutel. Hetzelfde sleutelbestand mag op meerdere sites worden gebruikt. Hun meldingen delen dan het quotum van het Google Cloud-project van de sleutel.','The settings screen has no option for pages, edits, old posts or categories'=>'Het instellingenscherm heeft geen optie voor pagina\'s, bewerkingen, oude berichten of categorieën','These options are part of the premium plan, which is a separate package. The free version from WordPress.org does not contain their code, so nothing on the screen is locked; the options are simply not there. Settings explained says which options belong to the premium plan.'=>'Deze opties horen bij het premiumplan, een apart pakket. De gratis versie van WordPress.org bevat hun code niet, dus op het scherm is niets vergrendeld; de opties zijn er gewoon niet. Instellingen uitgelegd zegt welke opties bij het premiumplan horen.','Read the Premium box on the settings screen and the FAQ entry about the premium plan. If you bought the plan, install the premium package as that entry describes.'=>'Lees het Premium-vak op het instellingenscherm en het FAQ-item over het premiumplan. Heb je het plan gekocht, installeer het premiumpakket dan zoals dat item beschrijft.','What does Fast Index send to Google?'=>'Wat verzendt Fast Index naar Google?','Only the address (URL) of a post and the kind of notification: %1$s when a post is published or changed, %2$s when it is removed. Titles, content, visitors and your database are not sent. To prove who is asking, Fast Index also sends a signed request that contains the email address and key ID of your service account; the private key itself never leaves your site. The requests go to oauth2.googleapis.com and indexing.googleapis.com. Your own History keeps the title, address and Google\'s answer in your database. See also %3$s.'=>'Alleen het adres (URL) van een bericht en het soort melding: %1$s wanneer een bericht wordt gepubliceerd of gewijzigd, %2$s wanneer het wordt verwijderd. Titels, inhoud, bezoekers en je database worden niet verzonden. Om te bewijzen wie het vraagt, stuurt Fast Index ook een ondertekend verzoek mee dat het e-mailadres en de sleutel-ID van je serviceaccount bevat; de privésleutel zelf verlaat je site nooit. De verzoeken gaan naar oauth2.googleapis.com en indexing.googleapis.com. Je eigen Geschiedenis bewaart de titel, het adres en het antwoord van Google in je database. Zie ook %3$s.','Google\'s privacy policy'=>'het privacybeleid van Google','Will Google index every page I publish right away?'=>'Indexeert Google elke pagina die ik publiceer meteen?','No, and Fast Index cannot promise it. Google says: %1$s For other pages, such as ordinary posts or products, Google may accept the notification and answer 200, but its documentation does not promise that the page will be crawled or indexed, or that this happens sooner. A 200 only means that, in Google\'s words, it "may try to recrawl this URL soon". Google also checks every submission for spam and may revoke access for abuse. Keep your sitemap and Search Console as they are. Details: %2$s.'=>'Nee, en Fast Index kan dat niet beloven. Google zegt: %1$s Voor andere pagina\'s, zoals gewone berichten of producten, kan Google de melding accepteren en met 200 antwoorden, maar de documentatie belooft niet dat de pagina wordt gecrawld of geïndexeerd, of dat dit sneller gebeurt. Een 200 betekent alleen dat Google, in zijn eigen woorden, “deze URL binnenkort opnieuw kan proberen te crawlen”. Google controleert ook elke inzending op spam en kan de toegang bij misbruik intrekken. Houd je sitemap en Search Console zoals ze zijn. Details: %2$s.','Using the Indexing API'=>'De Indexing API gebruiken','Which post types does Fast Index send?'=>'Welke berichttypen verzendt Fast Index?','Fast Index sends published content of the post types checked in the settings; drafts, pending and private posts are not sent. The free version offers Posts, which are checked by default.'=>'Fast Index verzendt gepubliceerde inhoud van de berichttypen die in de instellingen zijn aangevinkt; concepten, berichten in afwachting en privéberichten worden niet verzonden. De gratis versie biedt Berichten aan, standaard aangevinkt.','What happens when I trash or delete a post?'=>'Wat gebeurt er als ik een bericht naar de prullenbak verplaats of verwijder?','If Trash is checked in the settings, a published post that is moved to the trash, or deleted without the trash, is reported as %1$s with the address it had before. Deleting it later from the trash sends nothing more. Changing a published post to draft or private is not reported. Google asks that the address returns 404 or 410, or carries a noindex tag, when you send a removal (%2$s).'=>'Als Prullenbak in de instellingen is aangevinkt, wordt een gepubliceerd bericht dat naar de prullenbak wordt verplaatst, of zonder prullenbak wordt verwijderd, gemeld als %1$s met het adres dat het eerder had. Het later definitief verwijderen uit de prullenbak verzendt niets meer. Een gepubliceerd bericht wijzigen naar concept of privé wordt niet gemeld. Google vraagt dat het adres 404 of 410 teruggeeft, of een noindex-tag bevat, wanneer je een verwijdering verzendt (%2$s).','Google\'s documentation'=>'documentatie van Google','Can Fast Index send my old posts?'=>'Kan Fast Index mijn oude berichten verzenden?','Yes. Set a daily limit under %1$s. Every hour Fast Index sends a small random batch of published posts that Google has not accepted yet, newest first, until the daily limit is reached. The limit counts all successful notifications of the last 24 hours. %2$s runs one batch immediately, and History shows how many posts are still waiting. Keep the limit within Google\'s daily quota.'=>'Ja. Stel onder %1$s een dagelijkse limiet in. Elk uur verzendt Fast Index een kleine willekeurige batch gepubliceerde berichten die Google nog niet heeft geaccepteerd, nieuwste eerst, tot de dagelijkse limiet is bereikt. De limiet telt alle geslaagde meldingen van de afgelopen 24 uur. %2$s voert direct één batch uit en Geschiedenis toont hoeveel berichten nog wachten. Houd de limiet binnen het dagelijkse quotum van Google.','Send Old Posts Now'=>'Oude berichten nu verzenden','How many URLs can I send per day?'=>'Hoeveel URL\'s kan ik per dag verzenden?','Google\'s default is 200 publish requests per day for each Google Cloud project; notifications of both kinds, updated and removed, count (%s). Google says larger usage needs its approval and that quota may increase or decrease based on document quality. Fast Index does not know your quota in advance: when Google answers 429 it pauses that key for six hours.'=>'De standaardlimiet van Google is 200 publicatieverzoeken per dag per Google Cloud-project; meldingen van beide soorten, bijgewerkt en verwijderd, tellen mee (%s). Google zegt dat groter gebruik zijn goedkeuring vereist en dat het quotum kan toenemen of afnemen op basis van documentkwaliteit. Fast Index kent je quotum niet vooraf: wanneer Google met 429 antwoordt, pauzeert het die sleutel zes uur.','Can I use more than one service account?'=>'Kan ik meer dan één serviceaccount gebruiken?','With the premium plan you can upload several keys. For each notification Fast Index picks one of the keys that are not paused, in random order. If Google answers 401, 403 or 429 (or refuses the key), that key is paused for six hours and the next one is tried. Other errors (such as 400, 5xx or no answer) end the attempt without pausing a key. Note that Google counts quota for each project, not for each key, so keys from the same project share the same 200 per day. Google also writes that attempts to abuse the API, including the use of multiple accounts to exceed usage quotas, may result in access being revoked (%s). Use extra keys for reliability or for sites in separate projects, and ask Google for more quota if you need it.'=>'Met het premiumplan kun je meerdere sleutels uploaden. Voor elke melding kiest Fast Index in willekeurige volgorde een van de sleutels die niet gepauzeerd zijn. Als Google met 401, 403 of 429 antwoordt (of de sleutel weigert), wordt die sleutel zes uur gepauzeerd en wordt de volgende geprobeerd. Andere fouten (zoals 400, 5xx of geen antwoord) beëindigen de poging zonder een sleutel te pauzeren. Let op: Google telt quotum per project, niet per sleutel, dus sleutels uit hetzelfde project delen dezelfde 200 per dag. Google schrijft ook dat pogingen om de API te misbruiken, waaronder het gebruik van meerdere accounts om gebruikslimieten te overschrijden, ertoe kunnen leiden dat de toegang wordt ingetrokken (%s). Gebruik extra sleutels voor betrouwbaarheid of voor sites in aparte projecten, en vraag Google om meer quotum als je dat nodig hebt.','quickstart'=>'snelstartgids','Where is my service account key stored, and is it safe?'=>'Waar wordt mijn serviceaccountsleutel opgeslagen, en is dat veilig?','The key is kept in your WordPress database (an option that is not loaded on every request). It is never written to the uploads folder or any other file, and the screens show only the email address and key ID. Because the service account is an Owner of your Search Console property, treat the key like a password. If it may have leaked, delete the key in Google Cloud and remove the service account from the users of your Search Console property.'=>'De sleutel wordt bewaard in je WordPress-database (een optie die niet bij elk verzoek wordt geladen). Hij wordt nooit naar de uploadmap of een ander bestand geschreven en de schermen tonen alleen het e-mailadres en de sleutel-ID. Omdat het serviceaccount Eigenaar is van je Search Console-property, behandel je de sleutel als een wachtwoord. Als hij mogelijk is gelekt, verwijder je de sleutel in Google Cloud en verwijder je het serviceaccount uit de gebruikers van je Search Console-property.','What happens to my data if I deactivate or delete Fast Index?'=>'Wat gebeurt er met mijn gegevens als ik Fast Index deactiveer of verwijder?','Deactivating removes the scheduled tasks and keeps everything else. Deleting the plugin removes temporary data (queued tasks, caches, locks) and, by default, keeps your settings, keys and history, so a reinstall continues where you left off. If %s was checked before you deleted the plugin, settings, keys and history are removed too, on every site of a network. Records kept by Freemius are not touched, and the key stays valid in Google Cloud until you delete it there.'=>'Deactiveren verwijdert de geplande taken en laat al het andere staan. De plugin verwijderen wist tijdelijke gegevens (taken in de wachtrij, caches, vergrendelingen) en laat standaard je instellingen, sleutels en geschiedenis staan, zodat een herinstallatie verdergaat waar je gebleven was. Als %s was aangevinkt voordat je de plugin verwijderde, worden instellingen, sleutels en geschiedenis ook verwijderd, op elke site van een netwerk. Gegevens die Freemius bewaart, blijven ongemoeid en de sleutel blijft geldig in Google Cloud totdat je hem daar verwijdert.','I am upgrading from version 2.2. What happens to my keys?'=>'Ik upgrade van versie 2.2. Wat gebeurt er met mijn sleutels?','On the first page load after the update, Fast Index reads each key file that version 2.x saved in the uploads folder, checks it, stores it in the database and deletes the file. Your settings and history are kept, and the old ten-minute scheduled task is replaced by an hourly one. Earlier versions kept the files in a folder that anyone could reach, so a notice recommends creating new keys and deleting the old ones in Google Cloud (see Troubleshooting). If a file cannot be moved, a notice names it, and you can upload that key again.'=>'Bij het eerste laden van een pagina na de update leest Fast Index elk sleutelbestand dat versie 2.x in de uploadmap heeft opgeslagen, controleert het, slaat het op in de database en verwijdert het bestand. Je instellingen en geschiedenis blijven bewaard en de oude geplande taak van tien minuten wordt vervangen door een taak per uur. Eerdere versies bewaarden de bestanden in een map die voor iedereen bereikbaar was, dus een melding raadt aan nieuwe sleutels te maken en de oude in Google Cloud te verwijderen (zie Probleemoplossing). Als een bestand niet kan worden verplaatst, noemt een melding het en kun je die sleutel opnieuw uploaden.','Does Fast Index work on multisite?'=>'Werkt Fast Index op multisite?','Yes. You can activate it for the whole network or for single sites; sites created later are set up automatically after a network activation. Settings, keys, history and the schedule belong to each site, so upload a key on every site that should send. There is no network admin screen.'=>'Ja. Je kunt de plugin voor het hele netwerk of voor afzonderlijke sites activeren; sites die later worden gemaakt, worden na netwerkactivering automatisch ingesteld. Instellingen, sleutels, geschiedenis en het schema horen bij elke site, dus upload een sleutel op elke site die moet verzenden. Er is geen netwerkbeheerscherm.','Does Fast Index work on multilingual sites?'=>'Werkt Fast Index op meertalige sites?','Fast Index does not read language plugins. It sends the address that WordPress gives for the post that was saved, so a translation that is stored as its own post is sent when that post changes. The service account must be an Owner of a Search Console property that covers the addresses of every language, for example a Domain property. The plugin\'s own screens follow the language of your site or user profile.'=>'Fast Index leest geen taalplugins. Het verzendt het adres dat WordPress opgeeft voor het bericht dat is opgeslagen, dus een vertaling die als eigen bericht is opgeslagen, wordt verzonden wanneer dat bericht verandert. Het serviceaccount moet Eigenaar zijn van een Search Console-property die de adressen van elke taal dekt, bijvoorbeeld een domeinproperty. De schermen van de plugin zelf volgen de taal van je site of gebruikersprofiel.','Does Fast Index support Bing or IndexNow?'=>'Ondersteunt Fast Index Bing of IndexNow?','No. Fast Index talks only to the Google Indexing API.'=>'Nee. Fast Index praat alleen met de Google Indexing API.','What does the premium plan add?'=>'Wat voegt het premiumplan toe?','The free version is not limited in time or in the number of notifications. It notifies Google when a post is published, keeps a History of Google\'s answers and includes Help & FAQ.'=>'De gratis versie is niet beperkt in tijd of in het aantal meldingen. Ze brengt Google op de hoogte wanneer een bericht wordt gepubliceerd, houdt een geschiedenis bij van de antwoorden van Google en bevat Hulp en FAQ.','The premium plan is a separate package, sold through Freemius. The Premium box on the settings screen compares both versions, and %s in the Fast Index menu shows the plans and prices.'=>'Het premiumplan is een apart pakket, verkocht via Freemius. Het Premium-vak op het instellingenscherm vergelijkt beide versies, en %s in het menu van Fast Index toont de plannen en prijzen.','How do I get the premium plan, and how do I install it?'=>'Hoe krijg ik het premiumplan, en hoe installeer ik het?','Open %1$s in the Fast Index menu, or click %2$s on the settings screen, and buy a plan there; Freemius handles the payment. Freemius then emails you the premium package (a .zip file) and a license key; both are also in your account at %3$s. In WordPress go to Plugins, add a new plugin, click Upload Plugin and choose that .zip file, then activate it and enter the license key when you are asked. If both versions are installed, Freemius deactivates the free one. Your settings, keys and history are kept. The free version from WordPress.org never contains the premium code.'=>'Open %1$s in het menu van Fast Index, of klik op %2$s op het instellingenscherm, en koop daar een plan; Freemius regelt de betaling. Daarna mailt Freemius je het premiumpakket (een .zip-bestand) en een licentiesleutel; beide staan ook in je account op %3$s. Ga in WordPress naar Plugins, voeg een nieuwe plugin toe, klik op Plugin uploaden en kies dat .zip-bestand, activeer de plugin daarna en voer de licentiesleutel in wanneer daarom wordt gevraagd. Zijn beide versies geïnstalleerd, dan deactiveert Freemius de gratis versie. Je instellingen, sleutels en geschiedenis blijven bewaard. De gratis versie van WordPress.org bevat nooit de premiumcode.','Upgrade to Premium'=>'Upgraden naar Premium','What is Freemius, and do I have to connect an account?'=>'Wat is Freemius en moet ik een account koppelen?','No. Fast Index includes the Freemius SDK, which sells the premium plan and manages its licenses. The free version has no license screen. The first time you open Fast Index, Freemius shows an opt-in screen. If you choose %1$s, nothing is sent to Freemius and Fast Index works the same. If you choose %2$s, your browser sends what that screen lists to Freemius: your name and email address, the site address and title, the language, the WordPress, PHP, plugin and SDK versions, and later the list of your plugins and themes. Opening Upgrade loads the plans from Freemius without any site data, and choosing a plan opens the Freemius checkout. See %3$s.'=>'Nee. Fast Index bevat de Freemius SDK, die het premiumplan verkoopt en de licenties ervan beheert. De gratis versie heeft geen licentiescherm. De eerste keer dat je Fast Index opent, toont Freemius een opt-inscherm. Kies je %1$s, dan wordt er niets naar Freemius verzonden en werkt Fast Index hetzelfde. Kies je %2$s, dan stuurt je browser naar Freemius wat dat scherm opsomt: je naam en e-mailadres, het adres en de titel van de site, de taal, de versies van WordPress, PHP, de plugin en de SDK, en later de lijst van je plugins en thema\'s. Upgraden openen laadt de plannen van Freemius zonder gegevens van de site, en een plan kiezen opent de afrekenpagina van Freemius. Zie %3$s.','the Freemius privacy policy'=>'het privacybeleid van Freemius','Does Fast Index slow down saving posts?'=>'Vertraagt Fast Index het opslaan van berichten?','No. Saving a post only queues a scheduled task. The request to Google is made later by WP-Cron, with a time limit of 15 seconds, and a batch of old posts stops after about 20 seconds.'=>'Nee. Een bericht opslaan zet alleen een geplande taak in de wachtrij. Het verzoek aan Google wordt later door WP-Cron gedaan, met een tijdslimiet van 15 seconden, en een batch oude berichten stopt na ongeveer 20 seconden.','Read the Troubleshooting entry that matches the code in History, and the FAQ.'=>'Lees het item bij Probleemoplossing dat past bij de code in Geschiedenis, en de FAQ.','On the settings screen, look at the last answer shown next to each key.'=>'Kijk op het instellingenscherm naar het laatste antwoord naast elke sleutel.','In Search Console, check that the service account is an Owner of a property that matches your site address exactly.'=>'Controleer in Search Console of het serviceaccount Eigenaar is van een property die exact overeenkomt met je siteadres.','If WP_DEBUG_LOG is on, look in wp-content/debug.log for lines that mention fast-index.'=>'Als WP_DEBUG_LOG aan staat, zoek in wp-content/debug.log naar regels die fast-index noemen.','Search the support forum for your question first.'=>'Zoek eerst in het ondersteuningsforum naar je vraag.','When you write, say what you expected and what happened, and paste the system information below. Never post your JSON key file or any part of the private key.'=>'Vermeld in je bericht wat je verwachtte en wat er gebeurde, en plak de systeeminformatie hieronder. Plaats nooit je JSON-sleutelbestand of een deel van de privésleutel.','Choose what Fast Index sends to Google and upload the service account key. Each option is explained under its field and in Settings explained on the Help & FAQ screen.'=>'Kies wat Fast Index naar Google verzendt en upload de sleutel van het serviceaccount. Elke optie wordt uitgelegd onder het bijbehorende veld en bij Instellingen uitgelegd op het scherm Hulp en FAQ.','Shows the totals and the latest notifications with the answer from Google. 200 OK means Google accepted the notification; it does not mean the page is indexed. Other codes are explained under Troubleshooting.'=>'Toont de totalen en de laatste meldingen met het antwoord van Google. 200 OK betekent dat Google de melding heeft geaccepteerd; het betekent niet dat de pagina is geïndexeerd. Andere codes worden uitgelegd onder Probleemoplossing.','Sends one batch of old posts now, within the daily limit set on the settings screen. The batch has a random size, so a run can send nothing. The same batch also runs every hour.'=>'Verzendt nu één batch oude berichten, binnen de dagelijkse limiet die op het instellingenscherm is ingesteld. De batch heeft een willekeurige grootte, dus een uitvoering kan niets verzenden. Dezelfde batch draait ook elk uur.','Step-by-step setup, an explanation of every setting, troubleshooting, frequently asked questions and the system information to include when you ask for support.'=>'Stapsgewijze installatie, uitleg van elke instelling, probleemoplossing, veelgestelde vragen en de systeeminformatie die je meestuurt wanneer je om ondersteuning vraagt.','About this screen'=>'Over dit scherm','Open Help & FAQ'=>'Hulp en FAQ openen','For more information:'=>'Voor meer informatie:','Support forum'=>'Ondersteuningsforum','(external link, opens in a new tab)'=>'(externe link, opent in een nieuw tabblad)','System info copied.'=>'Systeeminfo gekopieerd.','System info is selected in the box above. Press Ctrl+C (Cmd+C on a Mac) to copy it.'=>'De systeeminfo is geselecteerd in het vak hierboven. Druk op Ctrl+C (Cmd+C op een Mac) om te kopiëren.','Yes'=>'Ja','No'=>'Nee','Fast Index version'=>'Fast Index-versie','WordPress version'=>'WordPress-versie','PHP version'=>'PHP-versie','Multisite'=>'Multisite','Site language'=>'Sitetaal','OpenSSL available'=>'OpenSSL beschikbaar','WP-Cron disabled (DISABLE_WP_CRON)'=>'WP-Cron uitgeschakeld (DISABLE_WP_CRON)','Premium plan features loaded'=>'Functies van het premiumplan geladen','Status setting'=>'Instelling Status','Passive'=>'Passief','Post types enabled'=>'Ingeschakelde berichttypen','Stored service account keys'=>'Opgeslagen serviceaccountsleutels','Keys available now (not paused)'=>'Nu beschikbare sleutels (niet gepauzeerd)','Last answer for each key'=>'Laatste antwoord per sleutel','Next hourly task'=>'Volgende taak (elk uur)','Not scheduled'=>'Niet gepland','Sent in the last 24 hours'=>'Verzonden in de afgelopen 24 uur','Posts waiting'=>'Wachtende berichten','Notifications waiting for a key'=>'Meldingen die op een sleutel wachten','Last notification'=>'Laatste melding','Key %1$d: %2$s'=>'Sleutel %1$d: %2$s','Not used yet'=>'Nog niet gebruikt','Nothing was sent yet.'=>'Er is nog niets verzonden.','The file could not be uploaded.'=>'Het bestand kon niet worden geüpload.','Fast Index History'=>'Fast Index-geschiedenis','Fast Index History Entry'=>'Fast Index-geschiedenisitem','Fast Index:'=>'Fast Index:','In earlier versions, service account key files were stored in a publicly accessible folder; for security, we recommend creating a new key in Google Cloud and revoking the old one.'=>'In eerdere versies werden sleutelbestanden van serviceaccounts opgeslagen in een openbaar toegankelijke map; voor de veiligheid raden we aan een nieuwe sleutel te maken in Google Cloud en de oude in te trekken.','Do not show this again'=>'Dit niet meer tonen','an unknown account'=>'een onbekend account','The key file of %s was not found. Upload the key again.'=>'Het sleutelbestand van %s is niet gevonden. Upload de sleutel opnieuw.','The key file of %1$s (uploads/%2$s) could not be read. Upload the key again, then delete the old file.'=>'Het sleutelbestand van %1$s (uploads/%2$s) kon niet worden gelezen. Upload de sleutel opnieuw en verwijder daarna het oude bestand.','The key file of %1$s (uploads/%2$s) is not a valid service account key. Upload the key again, then delete the old file.'=>'Het sleutelbestand van %1$s (uploads/%2$s) is geen geldige serviceaccountsleutel. Upload de sleutel opnieuw en verwijder daarna het oude bestand.','The key of %1$s was moved, but the old file uploads/%2$s could not be deleted. Delete this file now: it can be downloaded by anyone.'=>'De sleutel van %1$s is verplaatst, maar het oude bestand uploads/%2$s kon niet worden verwijderd. Verwijder dit bestand nu: iedereen kan het downloaden.','The key file of %1$s (%2$s) is not inside the uploads folder and was left untouched. Upload the key again, then delete the old file.'=>'Het sleutelbestand van %1$s (%2$s) staat niet in de uploadmap en is ongemoeid gelaten. Upload de sleutel opnieuw en verwijder daarna het oude bestand.','Publish'=>'Publiceren','Choose a valid status.'=>'Kies een geldige status.','Select at least one post type.'=>'Selecteer minstens één berichttype.','Post types: %s'=>'Berichttypen: %s','Edit'=>'Bewerken','Trash'=>'Prullenbak','Post events: %s'=>'Berichtgebeurtenissen: %s','Daily limit for old posts: %s'=>'Dagelijkse limiet voor oude berichten: %s','Excluded categories: %s'=>'Uitgesloten categorieën: %s','Service account keys after the first one: %s'=>'Serviceaccountsleutels na de eerste: %s','Fast Index is working.'=>'Fast Index werkt.','Google accepted a notification from this site.'=>'Google heeft een melding van deze site geaccepteerd.','If Fast Index is useful to you, a review on WordPress.org helps other site owners find it.'=>'Heb je iets aan Fast Index, dan helpt een beoordeling op WordPress.org andere site-eigenaren om het te vinden.','Rate Fast Index on WordPress.org'=>'Beoordeel Fast Index op WordPress.org','Title of the notice about the premium planFast Index Premium'=>'Fast Index Premium','The free version keeps working as it is.'=>'De gratis versie blijft werken zoals ze is.','The premium plan adds pages and custom post types, notifications for edits and removals, hourly batches of old posts, excluded categories and several service account keys.'=>'Het premiumplan voegt pagina\'s en aangepaste berichttypen toe, meldingen bij bewerken en verwijderen, batches per uur van oude berichten, uitgesloten categorieën en meerdere serviceaccountsleutels.','Notification when a post is published'=>'Melding wanneer een bericht wordt gepubliceerd','History of Google\'s answers, Help & FAQ'=>'Geschiedenis van de antwoorden van Google, Hulp en FAQ','Post types'=>'Berichttypen','Posts, pages and custom post types'=>'Berichten, pagina\'s en aangepaste berichttypen','Notifications for edits, trash and deletion'=>'Meldingen bij bewerken, prullenbak en verwijderen','Old posts in hourly batches, within a daily limit you set'=>'Oude berichten in batches per uur, binnen een dagelijkse limiet die je zelf instelt','Categories whose posts are never sent'=>'Categorieën waarvan de berichten nooit worden verzonden','Service account keys'=>'Serviceaccountsleutels','One'=>'Eén','Several; when Google pauses one, the next one is tried'=>'Meerdere; als Google er een pauzeert, wordt de volgende geprobeerd','This site also has %s. The premium plan can send them too.'=>'Deze site heeft ook %s. Het premiumplan kan die ook verzenden.','The premium plan can also send pages and custom post types.'=>'Het premiumplan kan ook pagina\'s en aangepaste berichttypen verzenden.','The premium plan also notifies Google when a published post is edited, trashed or deleted.'=>'Het premiumplan brengt Google ook op de hoogte wanneer een gepubliceerd bericht wordt bewerkt, naar de prullenbak gaat of wordt verwijderd.','The free version sends with one key. The premium plan keeps several keys and tries the next one when Google pauses a key.'=>'De gratis versie verzendt met één sleutel. Het premiumplan bewaart meerdere sleutels en probeert de volgende wanneer Google een sleutel pauzeert.','Badge next to a setting that the premium plan extendsPremium'=>'Premium','%s published post has not been accepted by Google yet. The premium plan can send old posts in hourly batches, within a daily limit you set.'=>'%s gepubliceerd bericht is nog niet door Google geaccepteerd. Het premiumplan kan oude berichten in batches per uur verzenden, binnen een dagelijkse limiet die je zelf instelt.' . "\0" . '%s gepubliceerde berichten zijn nog niet door Google geaccepteerd. Het premiumplan kan oude berichten in batches per uur verzenden, binnen een dagelijkse limiet die je zelf instelt.','The key of %1$s was saved and replaced the key of %2$s.'=>'De sleutel van %1$s is opgeslagen en heeft de sleutel van %2$s vervangen.','Link on the Plugins screenSettings'=>'Instellingen','The daily limit for old posts must be a whole number from 0 to %s.'=>'De dagelijkse limiet voor oude berichten moet een geheel getal van 0 tot %s zijn.','Sends one batch of old posts now, within the daily limit set on the settings screen. The same batch also runs every hour.'=>'Verzendt nu één batch oude berichten, binnen de dagelijkse limiet die op het instellingenscherm is ingesteld. Dezelfde batch draait ook elk uur.','Send now'=>'Nu verzenden','Number of old posts to send per day.'=>'Aantal oude berichten dat per dag wordt verzonden.','Select the categories to exclude.'=>'Selecteer de categorieën die je wilt uitsluiten.','Everything you need to set up Fast Index and to solve the most common problems. Read it before you write to support: the answer is most often here.'=>'Alles wat je nodig hebt om Fast Index in te stellen en de meest voorkomende problemen op te lossen. Lees dit voordat je contact opneemt met de ondersteuning: het antwoord staat hier meestal.','Help sections'=>'Helpsecties','Setting'=>'Instelling','What it does'=>'Wat het doet','Default'=>'Standaard','Change it when'=>'Wijzig het wanneer','Find what you see, then read why it happens and what to do.'=>'Zoek wat je ziet en lees dan waarom het gebeurt en wat je eraan kunt doen.','Why it happens:'=>'Waarom het gebeurt:','What to do:'=>'Wat je kunt doen:','Before you write to support, go through this list:'=>'Loop deze lijst door voordat je contact opneemt met de ondersteuning:','System info'=>'Systeeminfo','Read-only facts about your site that help us answer. They contain no keys and no email addresses.'=>'Alleen-lezen gegevens over je site die ons helpen antwoorden. Ze bevatten geen sleutels en geen e-mailadressen.','Copy system info'=>'Systeeminfo kopiëren','Open the Fast Index support forum on WordPress.org'=>'Open het Fast Index-ondersteuningsforum op WordPress.org','Updated'=>'Bijgewerkt','Deleted'=>'Verwijderd','Summary'=>'Overzicht','Total Sent'=>'Totaal verzonden','Total Waiting'=>'Totaal wachtend','Sent Today'=>'Vandaag verzonden','Date'=>'Datum','Send Status'=>'Verzendstatus','Post'=>'Bericht','Title'=>'Titel','Show more details'=>'Meer details tonen','View Post'=>'Bericht bekijken','Pagination'=>'Paginering','Previous'=>'Vorige','Next'=>'Volgende','Heading of the Fast Index settings screenSettings'=>'Instellingen','Some of your settings belong to the premium plan. They are kept, but this version does not use them. They are used again when the premium package is installed and its license is active.'=>'Sommige van je instellingen horen bij het premiumplan. Ze blijven bewaard, maar deze versie gebruikt ze niet. Ze worden weer gebruikt wanneer het premiumpakket is geïnstalleerd en de licentie ervan actief is.','Switch sending on or off.'=>'Schakel het verzenden in of uit.','Choose when Google is notified.'=>'Kies wanneer Google op de hoogte wordt gebracht.','Delete all plugin data (settings, keys and history) when the plugin is deleted. This cannot be undone.'=>'Verwijder alle plugingegevens (instellingen, sleutels en geschiedenis) wanneer de plugin wordt verwijderd. Dit kan niet ongedaan worden gemaakt.','Key ID: %s'=>'Sleutel-ID: %s','Used for sending'=>'Gebruikt voor verzenden','Kept, not used by this version'=>'Bewaard, niet gebruikt door deze versie','Delete'=>'Verwijderen','The key file is read and stored in the database; it is not saved in the uploads folder. Only the email address and the key ID are shown here.'=>'Het sleutelbestand wordt gelezen en in de database opgeslagen; het wordt niet in de uploadmap bewaard. Alleen het e-mailadres en de sleutel-ID worden hier getoond.','A new key replaces the key that is used for sending.'=>'Een nieuwe sleutel vervangt de sleutel die voor verzenden wordt gebruikt.','Setting up for the first time, or something does not work? Step-by-step instructions, an explanation of every setting, solutions to common problems and answers to frequently asked questions are in Help & FAQ.'=>'Stel je Fast Index voor het eerst in, of werkt er iets niet? Stapsgewijze instructies, uitleg van elke instelling, oplossingen voor veelvoorkomende problemen en antwoorden op veelgestelde vragen staan in Hulp en FAQ.','Fast Index sends your addresses to the Google Indexing API. A 200 answer means Google accepted the notification; Google does not promise to index the page.'=>'Fast Index verzendt je adressen naar de Google Indexing API. Een 200-antwoord betekent dat Google de melding heeft geaccepteerd; Google belooft niet dat de pagina wordt geïndexeerd.','Heading of the box about the premium planPremium'=>'Premium','The premium plan is a separate package. What each version does:'=>'Het premiumplan is een apart pakket. Wat elke versie doet:','Feature'=>'Functie','Column of the comparison tableFree'=>'Gratis','Column of the comparison tablePremium'=>'Premium','Included'=>'Inbegrepen','Not included'=>'Niet inbegrepen']];